def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    # Attempt to extract coordinates from a Point-like object
    try:
        return {"x": value.x, "y": value.y}
    except AttributeError:
        # Fallback: if value is a tuple or list of two elements
        try:
            x, y = value[0], value[1]
            return {"x": x, "y": y}
        except Exception:
            raise TypeError("Unsupported type for dehydrate_point: %r" % type(value))

