def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Define the custom __init__ for the new subclass
    def __init__(self, x, y, srid=None, **kwargs):
        # Call the base Point constructor
        super(self.__class__, self).__init__(x, y)
        # Store the SRID if provided, mapping it if necessary
        if srid is not None:
            self.srid = srid_map.get(srid, srid)
        # Assign any additional fields passed via kwargs
        for field in fields:
            setattr(self, field, kwargs.get(field))
    # Build the class dictionary
    attrs = {
        "__init__": __init__,
        "fields": fields,
        "srid_map": srid_map,
    }
    # Create and return the new subclass of Point
    return type(name, (Point,), attrs)

