@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path length.
    """
    import traceback
    import os

    def shorten_path(path):
        parts = path.split(os.sep)
        if len(parts) > max_path_level:
            return os.sep.join(parts[-max_path_level:])
        return path

    def _format(exc):
        lines = []
        # Exception type and message
        lines.append(f"{exc.__class__.__name__}: {exc}")
        # Traceback
        tb = exc.__traceback__
        if tb:
            extracted = traceback.extract_tb(tb)
            # Limit to the last `max_level` frames
            extracted = extracted[-max_level:]
            lines.append("Traceback (most recent call last):")
            for frame in extracted:
                file_path = shorten_path(frame.filename)
                lines.append(f'  File "{file_path}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'    {frame.line.strip()}')
        # Handle chained exceptions
        if exc.__cause__:
            lines.append("The above exception was the direct cause of the following exception:")
            lines.extend(_format(exc.__cause__))
        elif exc.__context__ and not exc.__suppress_context__:
            lines.append("During handling of the above exception, another exception occurred:")
            lines.extend(_format(exc.__context__))
        return lines

    return "\n".join(_format(e))

