def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    result = []
    for base in classes:
        if base in result:
            continue
        # Skip this base if any other base in the list is a subclass of it
        if any(issubclass(other, base) and other is not base for other in classes):
            continue
        result.append(base)
    return result

