    # Determine the class to inspect
    cls = self if isinstance(self, type) else self.__class__

    def _get_desc(obj):
        # Prefer a custom 'description' attribute if present
        if hasattr(obj, "description"):
            return getattr(obj, "description")
        # For properties, use the fget docstring or the property docstring
        if isinstance(obj, property):
            return obj.fget.__doc__ or obj.__doc__
        # Fallback to the object's __doc__ if available
        return getattr(obj, "__doc__", None)

    attrs = {}
    # Inspect attributes defined directly on the class
    for name, obj in cls.__dict__.items():
        if name.startswith("_"):
            continue
        if callable(obj):
            continue
        attrs[name] = _get_desc(obj)

    if all:
        # Include attributes from base classes
        for base in cls.__mro__[1:]:
            for name, obj in base.__dict__.items():
                if name.startswith("_"):
                    continue
                if callable(obj):
                    continue
                if name in attrs:
                    continue
                attrs[name] = _get_desc(obj)

    return attrs

