def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        # If the item is a tuple or list, we need to decide how to handle it.
        if isinstance(item, (tuple, list)):
            # If it's a 2-tuple, treat it as an implements spec and keep it as is.
            if len(item) == 2:
                output.extend(item)
            else:
                # For longer tuples/lists, flatten each element.
                for sub in item:
                    # Recursively handle nested tuples/lists.
                    if isinstance(sub, (tuple, list)):
                        _normalizeargs([sub], output)
                    else:
                        output.append(sub)
        else:
            # For any other object (class, interface, etc.), just add it.
            output.append(item)

    return output

