def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    if getattr(self, "initial_value", None) is not None:
        # If bins already exist, set each to the initial value
        if hasattr(self, "bins"):
            self.bins = [self.initial_value] * len(self.bins)
        else:
            # No bins yet – create a single bin with the initial value
            self.bins = [self.initial_value]
    else:
        # Use the make_bins method if available
        if hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            # Fallback: empty list of bins
            self.bins = []

