def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Determine the iterable of points
    points_iter = None
    if hasattr(self, "points"):
        points_iter = self.points
    if points_iter is None:
        raise AttributeError("The object has no 'points' attribute.")
    # If points is a callable (e.g., a method), call it
    if callable(points_iter):
        points_iter = points_iter()
    # Build lines
    lines = []
    if header is not None:
        lines.append(str(header))
    for point in points_iter:
        # Each point is expected to be a tuple (coordinate, value)
        if not isinstance(point, (list, tuple)):
            # If point is not iterable, treat entire point as coordinate
            coord = point
            val = None
        else:
            if len(point) == 2:
                coord, val = point
            else:
                # If point has more than two elements, assume last is value
                coord = point[:-1]
                val = point[-1]
        # Convert coordinate to string parts
        if isinstance(coord, (list, tuple)):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]
        # Convert value to string parts
        if val is None:
            val_parts = []
        elif isinstance(val, (list, tuple)):
            val_parts = [str(v) for v in val]
        else:
            val_parts = [str(val)]
        # Combine parts
        line_parts = coord_parts + val_parts
        lines.append(separator.join(line_parts))
    return "\n".join(lines) + ("\n" if lines else "")

