def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure context has the expected structure
        if not isinstance(context, dict):
            raise TypeError("context must be a dict")
        if 'value' not in context or not isinstance(context['value'], dict):
            context['value'] = {}
        if 'error' not in context or not isinstance(context['error'], dict):
            context['error'] = {}

        # Determine the list of fields in the graph
        fields = getattr(self, "_fields", None)
        if fields is None:
            # Fallback: use attributes that are not private and not callable
            fields = [attr for attr in dir(self)
                      if not attr.startswith("_") and not callable(getattr(self, attr))]

        # Map coordinate indices to names
        coord_names = ["x", "y", "z"]

        for field in fields:
            # Skip if the attribute does not exist
            if not hasattr(self, field):
                continue
            value = getattr(self, field)

            if field.startswith("error_"):
                # Process error field
                base = field[6:]  # remove 'error_'
                # Split into field name and suffix (e.g., 'E_low' -> 'E', 'low')
                parts = base.split("_", 1)
                if not parts:
                    continue
                field_name = parts[0]
                suffix = parts[1] if len(parts) > 1 else ""

                # Find the index of the coordinate field
                try:
                    coord_index = fields.index(field_name)
                except ValueError:
                    # If the coordinate field is not found, skip this error
                    continue

                # Determine the coordinate name (x, y, z) if within first three
                if coord_index < len(coord_names):
                    coord = coord_names[coord_index]
                else:
                    # If more than three coordinates, use the field name itself
                    coord = field_name

                error_key = f"{coord}_{suffix}" if suffix else coord

                # Determine indices where error is non-zero/non-None
                indices = []
                if value is not None:
                    try:
                        # If value is a sequence, iterate
                        for i, val in enumerate(value):
                            if val:
                                indices.append(i)
                    except TypeError:
                        # If value is a scalar, treat as single index if non-zero
                        if value:
                            indices.append(0)

                # Append or set the indices in context['error']
                if error_key in context['error']:
                    # Merge indices if key already exists
                    existing = context['error'][error_key].get("index", [])
                    if isinstance(existing, list):
                        context['error'][error_key]["index"] = list(set(existing + indices))
                    else:
                        context['error'][error_key]["index"] = indices
                else:
                    context['error'][error_key] = {"index": indices}
            else:
                # Regular field: add to context['value'] if not already present
                if field not in context['value']:
                    context['value'][field] = value
                else:
                    # Preserve existing value; do not overwrite
                    pass
        # No return value; context is modified in place.

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Avoid treating strings as iterables of characters
    if isinstance(seq, (str, bytes)):
        return False

    # If seq itself is a Source instance, reject
    if isinstance(seq, Source):
        return False

    # If seq is a single FillRequest, accept
    if isinstance(seq, FillRequest):
        return True

    # Otherwise, try to iterate and look for any FillRequest
    try:
        return any(isinstance(item, FillRequest) for item in seq)
    except TypeError:
        # seq is not iterable
        return False

