def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes resource
    manifest. Non-list and non-dict values are replaced with None. When `first_level`
    is True, identifying fields (apiVersion, kind, metadata.name, metadata.namespace)
    are copied from the original manifest; all other fields are set to None.

    Args:
        manifest_dict (dict): Partial Kubernetes resource.
        first_level (bool, optional): True if this dict represents the top-level
            observer_schema for a resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    if not isinstance(manifest_dict, dict):
        # If the input is not a dict, return None (should not happen in normal use)
        return None

    result = {}
    for key, value in manifest_dict.items():
        # Handle nested dictionaries recursively
        if isinstance(value, dict):
            if key == "metadata" and first_level:
                # Process metadata specially to preserve name and namespace
                nested = generate_default_observer_schema_dict(value, first_level=False)
                # Preserve identifying fields from the original manifest
                if "name" in value:
                    nested["name"] = value["name"]
                if "namespace" in value:
                    nested["namespace"] = value["namespace"]
                result[key] = nested
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Keep lists unchanged; their contents will be processed elsewhere
            result[key] = value
        else:
            # Non-dict and non-list values
