def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    import re

    # Retrieve styles from the instance
    in_style = getattr(self, "in_style", None)
    out_style = getattr(self, "out_style", None)
    if in_style is None or out_style is None:
        raise AttributeError("Both in_style and out_style must be defined on the instance")

    # If styles are identical, just return the original SQL and params as a list
    if in_style == out_style:
        return sql, list(many_params)

    # Work with string representation for regex processing
    is_bytes = isinstance(sql, bytes)
    sql_str = sql.decode() if is_bytes else sql

    # Helper to determine if a style is named
    def _is_named(style: str) -> bool:
        return style.startswith(":") or style.startswith("%(")

    in_named = _is_named(in_style)
    out_named = _is_named(out_style)

    # Prepare placeholder patterns
    if in_named:
        if in_style.startswith(":"):
            in_pattern = r":(\w+)"
        else:  # "%(name)s"
            in_pattern = r"%\((\w+)\)s"
    else:
        if in_style == "?":
            in_pattern = r"\?"
        elif in_style == "%s":
            in_pattern = r"%s"
        else:
            # Fallback: treat any non-named placeholder as a single '?'
            in_pattern = r"\?"

    # Determine placeholder names/order
    if in_named:
        names = re.findall(in_pattern, sql_str)
    else:
        # Count placeholders for ordinal styles
        names = [f"param{i+1}" for i in range(re.findall(in_pattern, sql_str).__len__())]

    # Build the new SQL string
    if in_named and out_named:
        # Replace the prefix if styles differ
        if in_style == out_style:
            new_sql = sql_str
        else:
            # Replace named placeholders with new prefix
            if out_style == ":":
                new_sql = re.sub(in_pattern, r":\1", sql_str)
            else:
                # Assume out_style is "%(name)s"
                new_sql = re.sub(in_pattern, r"%(\1)s", sql_str)
    elif in_named and not out_named:
        # Convert named placeholders to ordinal '?'
        new_sql = re.sub(in_pattern, "?", sql_str)
    elif not in_named and out_named:
        # Convert ordinal placeholders to named
        def repl(match):
            return f":{names.pop(0)}"

        new_sql = re.sub(in_pattern, repl, sql_str)
    else:
        # Both ordinal: keep as is
        new_sql = sql_str

    # Convert parameters
    out_params_list: List[Any] = []
    for params in many_params:
        if out_named:
            if in_named:
                # params is a dict; keep the same keys
                out_params_list.append({name: params[name] for name in names})
            else:
                # params is a sequence; map to generated names
                out_params_list.append({f"param{i+1}": val for i, val in enumerate(params)})
        else:
            if in_named:
                # params is a dict; produce list in order of names
                out_params_list.append([params[name] for name in names])
            else:
                # params is a sequence; keep as list
                out_params_list.append(list(params))

    # Encode back to bytes if needed
    if is_bytes:
        new_sql = new_sql.encode()

    return new_sql, out_params_list

