def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Ensure the path exists and is a directory
        if not self.fs.isdir(path):
            return False

        # Check for the mandatory .ocfl_version file
        version_file = self.fs.path.join(path, ".ocfl_version")
        if not self.fs.isfile(version_file):
            return False

        # Read and validate the version string
        with self.fs.open(version_file, "r") as f:
            version = f.read().strip()
        if version not in ("1.0", "1.1"):
            return False

        # If this is a repository root, validate the objects directory
        objects_dir = self.fs.path.join(path, "objects")
        if self.fs.isdir(objects_dir):
            for obj_name in self.fs.listdir(objects_dir):
                obj_path = self.fs.path.join(objects_dir, obj_name)
                if not self.fs.isdir(obj_path):
                    continue  # skip non-directories
                # Each object must contain a manifest.json
                manifest = self.fs.path.join(obj_path, "manifest.json")
                if not self.fs.isfile(manifest):
                    return False

        # If this is an individual object, check for required structure
        # (e.g., a content directory and a manifest.json)
        content_dir = self.fs.path.join(path, "content")
        if self.fs.isdir(content_dir):
            # Ensure at least one file exists in content
            if not self.fs.listdir(content_dir):
                return False
        else:
            # If no content directory, object is invalid
            return False

        return True
    except Exception:
        return False

