def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checks
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine spec version
    type_to_version = {
        "inventory_v1": "1.0",
        "inventory_v2": "2.0",
        "inventory_v3": "3.0",
    }

    if extract_spec_version:
        inv_type = inventory.get("type")
        if inv_type in type_to_version:
            self.spec_version = type_to_version[inv_type]
        else:
            # If type is missing or unknown, keep existing spec_version
            pass

    # Ensure spec_version is set
    if not hasattr(self, "spec_version") or self.spec_version is None:
        raise ValueError("Specification version is not set")

    # Version-specific validation
    if self.spec_version == "1.0":
        required_keys = {"name", "items"}
        if not required_keys.issubset(inventory):
            missing = required_keys - inventory.keys()
            raise ValueError(f"Missing required keys for spec 1.0: {missing}")
        if not isinstance(inventory["items"], list):
            raise ValueError("`items` must be a list in spec 1.0")
        # Each item should be a dict with at least an 'id' field
        for idx, item in enumerate(inventory["items"]):
            if not isinstance(item, dict):
                raise ValueError(f"Item at index {idx} is not a dict")
            if "id" not in item:
                raise ValueError(f"Item at index {idx} missing 'id' field")
    elif self.spec_version == "2.0":
        required_keys = {"metadata", "entries"}
        if not required_keys.issubset(inventory):
            missing = required_keys - inventory.keys()
            raise ValueError(f"Missing required keys for spec 2.0: {missing}")
        if not isinstance(inventory["entries"], list):
            raise ValueError("`entries` must be a list in spec 2.0")
        for idx, entry in enumerate(inventory["entries"]):
            if not isinstance(entry, dict):
                raise ValueError(f"Entry at index {idx} is not a dict")
            if "ref" not in entry:
                raise ValueError(f"Entry at index {idx} missing 'ref' field")
    elif self.spec_version == "3.0":
        # Example validation for a hypothetical spec 3.0
        if "components" not in inventory:
            raise ValueError("Missing 'components' key for spec 3.0")
        if not isinstance(inventory["components"], list):
            raise ValueError("`components` must be a list in spec 3.0")
        for idx, comp in enumerate(inventory["components"]):
            if not isinstance(comp, dict):
                raise ValueError(f"Component at index {idx} is not a dict")
            if "type" not in comp or "config" not in comp:
                raise ValueError(f"Component at index {idx} missing 'type' or 'config'")
    else:
        raise ValueError(f"Unsupported specification version: {self.spec_version}")

    # If all checks pass, return True
    return True

