def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to normalize inventory into a mapping: version -> {logical_path: set(content_files)}
    def normalize(inv):
        if isinstance(inv, dict):
            # Assume keys are versions and values are path mappings
            norm = {}
            for ver, paths in inv.items():
                # Ensure each path mapping is a dict of logical_path -> iterable of files
                norm[ver] = {}
                for lp, files in paths.items():
                    norm[ver][lp] = set(files)
            return norm
        elif isinstance(inv, list):
            norm = {}
            for entry in inv:
                ver = entry.get('version')
                paths = entry.get('paths', {})
                norm[ver] = {}
                for lp, files in paths.items():
                    norm[ver][lp] = set(files)
            return norm
        else:
            raise TypeError("Unsupported inventory format")

    norm_inv = normalize(inventory)

    # Sort versions to ensure deterministic order
    sorted_versions = sorted(norm_inv.keys())

    result = {}
    for ver in sorted_versions:
        if ver < version:
            continue
        paths = norm_inv[ver]
        if ver == version:
            # Initialize result with paths from the target version
            for lp, files in paths.items():
                result[lp] = set(files)
        else:
            # For later versions, add duplicate files to existing logical paths
            for lp, files in paths.items():
                if lp in result:
                    result[lp].update(files)
    return result

