def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Accept either a list of entries or a dict mapping file names to details
    if isinstance(fixity, dict):
        entries = list(fixity.values())
    elif isinstance(fixity, list):
        entries = fixity
    else:
        raise ValueError("Fixity block must be a list or dict")

    supported_algorithms = {"md5", "sha1", "sha256", "sha512"}

    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("Each fixity entry must be a dictionary")

        # Required keys
        for key in ("file", "hash", "algorithm"):
            if key not in entry:
                raise ValueError(f"Fixity entry missing required key: '{key}'")

        file_path = entry["file"]
        if file_path not in manifest_files:
            raise ValueError(f"Fixity entry references unknown file: {file_path}")

        # Validate hash format (hex string)
        hash_val = entry["hash"]
        if not isinstance(hash_val, str) or not all(c in "0123456789abcdefABCDEF" for c in hash_val):
            raise ValueError(f"Invalid hash value for file '{file_path}': {hash_val}")

        # Validate algorithm
        algo = entry["algorithm"].lower()
        if algo not in supported_algorithms:
            raise ValueError(f"Unsupported algorithm '{algo}' for file '{file_path}'")

    return True  # If no exception was raised, the fixity block is considered valid

