def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _pretty(obj, level):
        space = ' ' * (level * 4)
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                val = _pretty(v, level + 1)
                if debug:
                    val += f" ({type(v).__name__})"
                items.append(f"{space}{repr(k)}: {val}")
            return "{\n" + ",\n".join(items) + f"\n{space}}}"
        elif isinstance(obj, (list, tuple, set)):
            cls = type(obj).__name__
            items = []
            for v in obj:
                val = _pretty(v, level + 1)
                if debug:
                    val += f" ({type(v).__name__})"
                items.append(f"{space}{val}")
            sep = ',\n'
            if isinstance(obj, list):
                opening, closing = '[', ']'
            elif isinstance(obj, tuple):
                opening, closing = '(', ')'
            else:
                opening, closing = '{', '}'
            return f"{opening}\n" + sep.join(items) + f"\n{space}{closing}"
        elif hasattr(obj, "__dict__"):
            cls_name = obj.__class__.__name__
            items = []
            for k, v in obj.__dict__.items():
                val = _pretty(v, level + 1)
                if debug:
                    val += f" ({type(v).__name__})"
                items.append(f"{space}{k}={val}")
            return f"{cls_name}(\n" + ",\n".join(items) + f"\n{space})"
        else:
            return repr(obj)

    return _pretty(self, indent)

