def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    # First try to read a VERSION file in the same directory
    try:
        version_file = os.path.join(os.path.dirname(__file__), "VERSION")
        with open(version_file, "r", encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        pass

    # Next try to get the distribution version via importlib.metadata
    try:
        try:
            from importlib.metadata import version, PackageNotFoundError
        except ImportError:
            from importlib_metadata import version, PackageNotFoundError
    except Exception:
        return "0.0.0"

    pkg_name = __package__ or __name__
    if pkg_name in ("__main__", ""):
        pkg_name = os.getenv("PACKAGE_NAME", "unknown")

    try:
        return version(pkg_name)
    except PackageNotFoundError:
        return "0.0.0"

