def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # If pieces is already a string, return it unchanged
    if isinstance(pieces, str):
        return pieces

    # Extract components from dict or iterable
    if isinstance(pieces, dict):
        major = pieces.get('major', 0)
        minor = pieces.get('minor', 0)
        patch = pieces.get('patch', 0)
        prerelease = pieces.get('prerelease')
        build = pieces.get('build')
    else:
        it = iter(pieces or [])
        major = next(it, 0)
        minor = next(it, 0)
        patch = next(it, 0)
        prerelease = next(it, None)
        build = next(it, None)

    # Convert numeric parts to strings
    major = str(major)
    minor = str(minor)
    patch = str(patch)

    # Helper to format prerelease/build parts
    def fmt_part(part):
        if part is None:
            return None
        if isinstance(part, (list, tuple)):
            return '.'.join(str(p) for p in part)
        return str(part)

    prerelease = fmt_part(prerelease)
    build = fmt_part(build)

    # Render according to style
    if style == 'semver':
        base = f"{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if build:
            base += f"+{build}"
        return base

    if style == 'pep440':
        base = f"{major}.{minor}.{patch}"
        if prerelease:
            # PEP 440 uses a dot before the prerelease part
            base += f".{prerelease}"
        if build:
            base += f"+{build}"
        return base

    if style == 'git':
        base = f"v{major}.{minor}.{patch}"
        if prerelease:
            base += f"-{prerelease}"
        if build:
            base += f"+{build}"
        return base

    # Default: join non-empty parts with dots
    parts = [major, minor, patch]
    if prerelease:
        parts.append(prerelease)
    if build:
        parts.append(build)
    return '.'.join(parts)

