def register_vcs_handler(vcs, method=None):
    """
    Decorator factory that registers a function as the handler for a given VCS.
    It can be used in two ways:

    1. As a decorator factory:
        @register_vcs_handler('git')
        def git_handler(...):
            ...

    2. Directly with the function:
        def git_handler(...):
            ...
        register_vcs_handler('git', git_handler)
    """
    if method is None:
        def decorator(func):
            _vcs_handlers[vcs] = func
            return func
        return decorator
    else:
        _vcs_handlers[vcs] = method
        return method

