def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Load the root inventory once if not already loaded
    if not hasattr(self, "_root_inventory"):
        root_path = os.path.join(self.base_path, "inventory.json")
        if not os.path.exists(root_path):
            raise FileNotFoundError(f"Root inventory not found at {root_path}")
        with open(root_path, "r", encoding="utf-8") as f:
            self._root_inventory = json.load(f)

    # Prepare a dict to record differences: {content_id: (root_digest, version_digest)}
    self._different_digests = {}

    # Iterate over each version directory in order
    for ver_dir in version_dirs:
        inv_path = os.path.join(self.base_path, ver_dir, "inventory.json")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Inventory missing for version directory '{ver_dir}' at {inv_path}")

        with open(inv_path, "r", encoding="utf-8") as f:
            try:
                version_inv = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to parse inventory JSON in '{inv_path}': {e}")

        # Ensure all keys in the version inventory exist in the root inventory
        missing_in_root = set(version_inv.keys()) - set(self._root_inventory.keys())
        if missing_in_root:
            raise ValueError(
                f"Inventory in '{ver_dir}' contains unknown content IDs: {sorted(missing_in_root)}"
            )

        # Record any digest differences compared to the root inventory
        for content_id, ver_digest in version_inv.items():
            root_digest = self._root_inventory.get(content_id)
            if root_digest is None:
                # This should not happen due to the previous check, but guard anyway
                continue
            if ver_digest != root_digest:
                self._different_digests.setdefault(content_id, []).append(
                    (ver_dir, root_digest, ver_digest)
                )

    # Return the collected differences for further validation if needed
    return self._different_digests

