def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"Path does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        # Look for a file named "0=*"
        namaste_file = None
        try:
            for entry in os.listdir(path):
                if entry.startswith('0=') and not entry.endswith('='):
                    # Ensure it's a file
                    full = os.path.join(path, entry)
                    if os.path.isfile(full):
                        namaste_file = entry
                        break
        except OSError as e:
            return f"Error accessing directory {path}: {e}"

        if not namaste_file:
            return f"No Namaste file (0=*) found in directory: {path}"

        # Determine if this is a root or an object
        # Root typically contains an "objects" subdirectory
        objects_dir = os.path.join(path, 'objects')
        if os.path.isdir(objects_dir):
            return 'root'
        else:
            return 'object'

    return f"Unknown path type: {path}"

