def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if params is None:
        params = {}
    elif not isinstance(params, dict):
        # If params is not a dict, try to convert it
        try:
            params = dict(params)
        except Exception:
            params = {}

    # If no bug_ids provided, nothing to amend
    if bug_ids is None:
        return params

    # Helper to extract id from various possible representations
    def _extract_id(item):
        if isinstance(item, (int, float)):
            return str(int(item))
        if isinstance(item, str):
            return item
        if isinstance(item, dict):
            if 'id' in item:
                return str(item['id'])
            if 'bug_id' in item:
                return str(item['bug_id'])
        if hasattr(item, 'id'):
            return str(item.id)
        if hasattr(item, 'bug_id'):
            return str(item.bug_id)
        # Fallback to string representation
        return str(item)

    # Build the ids string
    if isinstance(bug_ids, (list, tuple, set)):
        ids_list = [_extract_id(b) for b in bug_ids]
        ids_str = ','.join(ids_list)
    else:
        # Single id or string
        ids_str = _extract_id(bug_ids)

    # Amend the params dictionary
    params['ids'] = ids_str
    return params

