                    if existing_val_node.tag == 'tag:yaml.org,2002:map' and val_node.tag == 'tag:yaml.org,2002:map':
                        merged_val = merge_mapping_nodes(existing_val_node, val_node)
                        merged[k] = (existing_key_node, merged_val)
                    else:
                        # Not both maps, last wins
                        merged[k] = (existing_key_node, val_node)
                else:
                    merged[k] = (existing_key_node, val_node)
            else:
                merged[k] = (key_node, val_node)
                order.append(k)
        # Build result list preserving order
        result = []
        for k in order:
            result.append(merged[k])
        return result

    # Main merging logic
    merged_dict = {}
    order = []
    for key_node, val_node in nodes:
        k = key_node.value
        if k in merged_dict:
            existing_key_node, existing_val_node = merged_dict[k]
            if hasattr(existing_val_node, 'tag') and hasattr(val_node, 'tag'):
                if existing_val_node.tag == 'tag:yaml.org,2002:map' and val_node.tag == 'tag:yaml.org,2002:map':
                    merged_val = merge_mapping_nodes(existing_val_node, val_node)
                    merged_dict[k] = (existing_key_node, merged_val)
                else:
                    merged_dict[k] = (existing_key_node, val_node)
            else:
                merged_dict[k] = (existing_key_node, val_node)
        else:
            merged_dict[k] = (key_node, val_node)
            order.append(k)
    # Build final list preserving order
    result = []
    for k in order:
        result.append(merged_dict[k])
    return result

