def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    parsed = {}
    i = 0
    n = len(arguments)
    while i < n:
        arg = arguments[i]
        if arg.startswith("--"):
            key = arg[2:]
            if i + 1 < n and not arguments[i + 1].startswith("-"):
                parsed[key] = arguments[i + 1]
                i += 2
            else:
                parsed[key] = True
                i += 1
        elif arg.startswith("-"):
            key = arg[1:]
            if i + 1 < n and not arguments[i + 1].startswith("-"):
                parsed[key] = arguments[i + 1]
                i += 2
            else:
                parsed[key] = True
                i += 1
        else:
            parsed.setdefault("positional", []).append(arg)
            i += 1
    # Create a simple Namespace-like object to hold the parsed values
    Namespace = type("Namespace", (object,), {})
    ns = Namespace()
    for k, v in parsed.items():
        setattr(ns, k, v)
    return ns

