        'second': 'seconds',
        'seconds': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unknown unit in frequency: {frequency}")
    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

