def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine name and default from various possible matcher types
    name = None
    default = None

    # Regex match object
    if hasattr(matcher, "group"):
        try:
            name = matcher.group(1)
        except Exception:
            pass
        try:
            default = matcher.group(2)
        except Exception:
            default = None

    # Tuple or list
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]

    # Dictionary
    elif isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")

    # String
    elif isinstance(matcher, str):
        name = matcher

    # If name is still None, cannot resolve
    if name is None:
        raise ValueError("Matcher does not contain a variable name")

    # Fetch from environment
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not set and no default provided.")
    return value

