def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import logging
    import re

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            # Replace ${VAR} or $VAR with environment variable
            pattern = re.compile(r'\$\{([^}]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)')
            def repl(match):
                var = match.group(1) or match.group(2)
                return os.getenv(var, '')
            return pattern.sub(repl, value)
        return value

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(_resolve_env_in_value(v)) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(_resolve_env_in_value(v)) for v in d]
        else:
            return _resolve_env_in_value(d)

    parsed_configs = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                config = json.load(f)
        except Exception as exc:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to load configuration from {filename}: {exc}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        if overrides:
            if isinstance(config, dict):
                config.update(overrides)
            else:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Overrides provided but configuration from {filename} is not a dict',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

        if resolve_env:
            try:
                config = _resolve_env_in_dict(config)
            except Exception as exc:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Environment variable resolution failed for {filename}: {exc}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

        parsed_configs[filename] = config

    return parsed_configs, error_records

