def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, ensure it is compatible with all bases
    if explicit_mc is not None:
        for base in bases:
            if not issubclass(explicit_mc, type(base)):
                raise TypeError(
                    f"metaclass conflict: {explicit_mc} is not a subclass of {type(base)}"
                )
        return explicit_mc

    # No explicit metaclass; determine the most derived metaclass from the bases
    if not bases:
        return type

    metaclasses = [type(b) for b in bases]
    most_derived = None
    for candidate in metaclasses:
        if all(issubclass(candidate, other) for other in metaclasses):
            if most_derived is not None:
                raise TypeError("metaclass conflict: multiple metaclasses found")
            most_derived = candidate

    if most_derived is None:
        raise TypeError("metaclass conflict: no common metaclass found")

    return most_derived

