def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Empty tags are not allowed
    if not tag:
        return False
    # Maximum length constraint (common in many tag systems)
    if len(tag) > 30:
        return False
    # Tags must start and end with a letter or digit
    if not (tag[0].isalnum() and tag[-1].isalnum()):
        return False
    # Allowed characters: lowercase letters, digits, and hyphens
    prev_dash = False
    has_letter = False
    for ch in tag:
        if ch.isalpha():
            if not ch.islower():
                return False
            has_letter = True
        elif ch.isdigit():
            pass
        elif ch == '-':
            if prev_dash:
                # No consecutive hyphens
                return False
            prev_dash = True
            continue
        else:
            # Any other character is disallowed
            return False
        prev_dash = False
    # At least one letter is required
    return has_letter

