def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = {}
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links[rel] = href
        return {"subject": subject, "aliases": aliases, "links": links}
    except json.JSONDecodeError:
        # Fallback to XRD (XML)
        try:
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_elem = root.find("xrd:Subject", ns)
            subject = subject_elem.text if subject_elem is not None else None
            aliases = [a.text for a in root.findall("xrd:Alias", ns) if a.text]
            links = {}
            for link_elem in root.findall("xrd:Link", ns):
                rel = link_elem.attrib.get("rel")
                href = link_elem.attrib.get("href")
                if rel and href:
                    links[rel] = href
            return {"subject": subject, "aliases": aliases, "links": links}
        except ET.ParseError:
            raise ValueError("Invalid webfinger document")

