@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided")

        # Import yaml lazily to avoid unnecessary dependency if method is never called
        try:
            import yaml
        except ImportError as exc:
            raise IRValidatorException("PyYAML is required to load YAML files") from exc

        # Resolve the file path
        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
        except Exception as exc:
            raise IRValidatorException(f"Error reading YAML file {yaml_file}: {exc}") from exc

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a top-level mapping")

        # Determine required fields.  Subclasses may define a class attribute
        # `REQUIRED_FIELDS` as an iterable of keys that must be present.
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in data]
        if missing:
            missing_str = ", ".join(missing)
            raise IRValidatorException(f"Missing required field(s) in YAML file: {missing_str}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Keep track of already processed include files to avoid infinite recursion.
    processed_files = set()

    def merge_dicts(target, source):
        """Recursively merge source dict into target dict."""
        for key, value in source.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                merge_dicts(target[key], value)
            else:
                target[key] = value

    def resolve(d):
        """Recursively resolve include directives in a dict or list."""
        if isinstance(d, dict):
            # Find include keys at this level
            include_keys = [k for k in d if k in ("$include", "include")]
            for key in include_keys:
                include_value = d.pop(key)
                # Normalize to a list of paths
                if isinstance(include_value, str):
                    paths = [include_value]
                elif isinstance(include_value, list):
                    paths = include_value
                else:
                    continue  # Unsupported format, skip

                for path in paths:
                    if path in processed_files:
                        continue
                    processed_files.add(path)
                    # Load the included spec (assumes self._load_file returns a dict)
                    included = self._load_file(path)
                    if included is None:
                        continue
                    merge_dicts(d, included)
                    # Resolve any includes inside the newly merged content
                    resolve(d)

            # Resolve nested structures
            for value in d.values():
                resolve(value)

        elif isinstance(d, list):
            for item in d:
                resolve(item)

    resolve(parser_dict)
    return parser_dict

