def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    Returns:
        dict: A mapping of argument names to their resolved default values.
    """
    defaults = {}
    # Retrieve the specification and already provided arguments, if any.
    spec = getattr(self, "spec", {})
    provided = getattr(self, "args", {})
    for name, spec_item in spec.items():
        # Skip arguments that have already been supplied.
        if name in provided:
            continue
        # Use the default defined in the spec, if present.
        if "default" in spec_item:
            value = spec_item["default"]
            # Attempt to cast the value to the declared type, if any.
            if "type" in spec_item:
                try:
                    value = spec_item["type"](value)
                except Exception:
                    # If casting fails, keep the original value.
                    pass
            defaults[name] = value
    return defaults

