    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be a dict, list, tuple, or any iterable of values.
    :return: True if all numeric values are within [self.min, self.max], otherwise raises ValueError.
    """
    # Ensure min and max attributes exist
    if not hasattr(self, "min") or not hasattr(self, "max"):
        raise AttributeError("Object must have 'min' and 'max' attributes for validation.")

    # If args is a dict, use its values; otherwise treat it as an iterable of values
    if isinstance(args, dict):
