    # Iterate over each value and validate
    for val in values:
        # Skip non-numeric values
        if not isinstance(val, (int, float)):
            continue
        if val < self.min or val > self.max:
            raise ValueError(
                f"Argument value {val} out of bounds [{self.min}, {self.max}]"
